with ranked as (
  select ctid, source_relative_path, resource_key,
         row_number() over (partition by source_relative_path order by resource_key) as rn
  from expected_drive_metadata_import_027
)
update expected_drive_metadata_import_027 i
set source_relative_path = i.source_relative_path || ' [' || i.resource_key || ']'
from ranked r
where i.ctid = r.ctid and r.rn > 1;

select is((select count(*) from expected_drive_metadata_import_027),316::bigint,'Prompt 027 manifest has exactly 316 controlled imported files.');
select is((select count(distinct id) from expected_drive_metadata_import_027),316::bigint,'Prompt 027 UUIDs are unique.');
select is((select count(distinct resource_key) from expected_drive_metadata_import_027),316::bigint,'Prompt 027 resource keys are unique.');
select is((select count(*) from expected_drive_metadata_import_027 where nullif(trim(source_relative_path),'') is not null),316::bigint,'Prompt 027 every imported file has a nonblank source relative path.');
select is((select count(distinct source_drive_file_id) from expected_drive_metadata_import_027),316::bigint,'Prompt 027 Drive file IDs are unique.');
select is((select count(*) from expected_drive_metadata_import_027 where resource_type='folder'),0::bigint,'Prompt 027 imports no folders as resources.');

select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%'),316::bigint,'Database contains exactly 316 Prompt 027 Drive metadata rows.');
select is((select count(*) from app.academic_module_resources where resource_key like 'l1-%' or resource_key like 'drive-l1-%'),1263::bigint,'Database contains 947 existing BUC seed resources plus 316 Prompt 027 resources.');
select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%' and source_drive_file_id is null),0::bigint,'Every Prompt 027 row has a Drive file ID.');
select is((select count(distinct source_drive_file_id) from app.academic_module_resources where resource_key like 'drive-l1-%'),316::bigint,'Prompt 027 persisted Drive file IDs remain unique.');

select is((select count(*)
from expected_drive_metadata_import_027 e
join app.academic_modules m on m.code=e.module_code
join app.academic_module_resources r on r.id=e.id
where (
  r.academic_module_id, r.resource_key, r.source_relative_path, r.display_name, r.file_format, r.mime_type,
  r.resource_classification, r.distribution_review_status, r.publication_state, r.storage_object_path,
  r.source_provider, r.source_drive_file_id, r.source_title, r.source_file_size_bytes, r.source_folder_path,
  r.resource_type, r.resource_category, r.approval_state, r.visibility_state, r.manual_review_required, r.approval_required, r.student_publish_default
) is not distinct from (
  m.id, e.resource_key, e.source_relative_path, e.display_name, e.file_format, e.mime_type,
  e.resource_classification, e.distribution_review_status, e.publication_state, e.storage_object_path,
  e.source_provider, e.source_drive_file_id, e.source_title, e.source_file_size_bytes, e.source_folder_path,
  e.resource_type, e.resource_category, e.approval_state, e.visibility_state, e.manual_review_required, e.approval_required, e.student_publish_default
)),316::bigint,'Every Prompt 027 row matches the exact controlled metadata tuple.');

select is((select count(*) from app.academic_module_resources r left join expected_drive_metadata_import_027 e on e.id=r.id where r.resource_key like 'drive-l1-%' and e.id is null),0::bigint,'No extra Prompt 027 metadata row exists outside its manifest.');
select is((select count(*) from ((select module_code,count(*) n from expected_drive_metadata_import_027 group by module_code) except (select m.code,count(*) n from app.academic_module_resources r join app.academic_modules m on m.id=r.academic_module_id where r.resource_key like 'drive-l1-%' group by m.code)) d),0::bigint,'Persisted Prompt 027 module counts match the manifest.');
select is((select count(*) from ((select resource_type,count(*) n from expected_drive_metadata_import_027 group by resource_type) except (select resource_type,count(*) n from app.academic_module_resources where resource_key like 'drive-l1-%' group by resource_type)) d),0::bigint,'Persisted Prompt 027 resource-type counts match the manifest.');
select is((select count(*) from ((select resource_category,count(*) n from expected_drive_metadata_import_027 group by resource_category) except (select resource_category,count(*) n from app.academic_module_resources where resource_key like 'drive-l1-%' group by resource_category)) d),0::bigint,'Persisted Prompt 027 category counts match the manifest.');

select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%' and storage_object_path is not null),0::bigint,'Prompt 027 adds no storage object path.');
select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%' and student_publish_default),0::bigint,'Prompt 027 adds no student-publishable resource.');
select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%' and not approval_required),0::bigint,'Prompt 027 keeps approval required for every resource.');
select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%' and publication_state <> 'not_published'),0::bigint,'Prompt 027 keeps every imported resource not published.');

select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%' and resource_type in ('question_bank','assessment_file') and (visibility_state <> 'restricted' or approval_state <> 'blocked' or distribution_review_status <> 'restricted' or publication_state <> 'not_published')),0::bigint,'Question-bank and assessment metadata remains restricted, blocked, and unpublished.');
select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%' and resource_type in ('recording','video') and (visibility_state <> 'restricted' or approval_state <> 'pending_review' or distribution_review_status <> 'restricted' or publication_state <> 'not_published')),0::bigint,'Video and recording metadata remains restricted, pending review, and unpublished.');
select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%' and resource_type in ('lecture_pdf','slide_deck','summary_pdf','practical_material') and (visibility_state <> 'draft' or approval_state <> 'pending_review' or publication_state <> 'not_published')),0::bigint,'Lecture, slide, summary, and practical metadata remains draft/pending-review and unpublished.');

select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%' and resource_type='question_bank'),23::bigint,'Prompt 027 imported high-confidence module-scoped question bank files only.');
select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%' and resource_type in ('recording','video')),82::bigint,'Prompt 027 imported 82 recording/video metadata rows.');
select is((select count(*) from app.academic_module_resources where resource_key like 'drive-l1-%' and resource_type in ('unknown','placement_test')),0::bigint,'Prompt 027 excludes unknown and placement-test files.');
select is((select count(*) from information_schema.columns where table_schema='app' and table_name='academic_module_resources' and column_name in ('drive_url','source_url','provider_id','permission_data','file_bytes','checksum','cdn_url','delivery_url','public_url','signed_url')),0::bigint,'Prompt 027 has no public/provider URL or payload columns.');
select is((select count(*) from information_schema.role_table_grants where table_schema='app' and table_name='academic_module_resources' and grantee in ('PUBLIC','anon','authenticated')),0::bigint,'Prompt 027 keeps no direct client table grants.');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='app' and p.prosecdef),0::bigint,'Prompt 027 adds no SECURITY DEFINER function.');

select * from finish();
rollback;
